<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: #1a1a1a;
            color: #ffffff;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        .container {
            text-align: center;
            background-color: #222222;
            padding: 30px;
            border-radius: 10px;
            box-shadow: 0 0 20px rgba(0, 0, 0, 0.5);
        }

        h1 {
            margin-bottom: 20px;
            color: #4CAF50;
            font-size: 2.5em;
        }

        #score {
            font-size: 1.5em;
            margin-bottom: 20px;
            color: #4CAF50;
        }

        #snake {
            display: block;
            background-color: #0a0a0a;
            border: 2px solid #4CAF50;
            margin: 0 auto 20px;
            box-shadow: 0 0 10px rgba(76, 175, 80, 0.3);
        }

        .controls {
            display: flex;
            gap: 10px;
            justify-content: center;
            margin-bottom: 15px;
        }

        button {
            padding: 10px 20px;
            font-size: 1em;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            background-color: #4CAF50;
            color: #ffffff;
            font-weight: bold;
            transition: background-color 0.3s;
        }

        button:hover {
            background-color: #45a049;
        }

        button:active {
            background-color: #3d8b40;
        }

        .info {
            font-size: 0.9em;
            color: #aaaaaa;
            margin-top: 15px;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>🐍 Snake</h1>
        <div id="score">Score: 0</div>
        <canvas id="snake" width="400" height="400"></canvas>
        <div class="controls">
            <button id="start">Start</button>
            <button id="pause">Pause</button>
            <button id="reset">Reset</button>
        </div>
        <div class="info">Use arrow keys to control the snake</div>
    </div>

    <script>
        // Game configuration
        const GRID_SIZE = 20;
        const CELL_SIZE = 400 / GRID_SIZE;

        // Game state
        const gameState = {
            snake: [[10, 10], [9, 10], [8, 10]],
            food: [15, 15],
            direction: 'right',
            nextDirection: 'right',
            score: 0,
            alive: true,
            running: false,
            gameLoop: null
        };

        const canvas = document.getElementById('snake');
        const ctx = canvas.getContext('2d');

        // Utility functions
        function drawCell(x, y, color) {
            ctx.fillStyle = color;
            ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
        }

        function drawBorder() {
            ctx.strokeStyle = '#4CAF50';
            ctx.lineWidth = 2;
            ctx.strokeRect(0, 0, canvas.width, canvas.height);
        }

        function draw() {
            // Clear canvas
            ctx.fillStyle = '#0a0a0a';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw border
            drawBorder();

            // Draw food
            ctx.fillStyle = '#FF6B6B';
            ctx.beginPath();
            ctx.arc(
                gameState.food[0] * CELL_SIZE + CELL_SIZE / 2,
                gameState.food[1] * CELL_SIZE + CELL_SIZE / 2,
                CELL_SIZE / 2 - 2,
                0,
                Math.PI * 2
            );
            ctx.fill();

            // Draw snake
            gameState.snake.forEach((segment, index) => {
                if (index === 0) {
                    // Head
                    ctx.fillStyle = '#4CAF50';
                } else {
                    // Body
                    ctx.fillStyle = '#66BB6A';
                }
                drawCell(segment[0], segment[1], index === 0 ? '#4CAF50' : '#66BB6A');
            });
        }

        function isColliding(x, y) {
            // Wall collision
            if (x < 0 || x >= GRID_SIZE || y < 0 || y >= GRID_SIZE) {
                return true;
            }
            // Body collision (skip head)
            for (let i = 1; i < gameState.snake.length; i++) {
                if (gameState.snake[i][0] === x && gameState.snake[i][1] === y) {
                    return true;
                }
            }
            return false;
        }

        function getNewFoodPosition() {
            let x, y;
            let valid = false;
            const snakeSet = new Set(gameState.snake.map(s => `${s[0]},${s[1]}`));

            while (!valid) {
                x = Math.floor(Math.random() * GRID_SIZE);
                y = Math.floor(Math.random() * GRID_SIZE);
                valid = !snakeSet.has(`${x},${y}`);
            }
            return [x, y];
        }

        function tick() {
            if (!gameState.alive) return;

            gameState.direction = gameState.nextDirection;

            const head = gameState.snake[0];
            let newX = head[0];
            let newY = head[1];

            switch (gameState.direction) {
                case 'up':
                    newY--;
                    break;
                case 'down':
                    newY++;
                    break;
                case 'left':
                    newX--;
                    break;
                case 'right':
                    newX++;
                    break;
            }

            if (isColliding(newX, newY)) {
                gameState.alive = false;
                gameState.running = false;
                if (gameState.gameLoop) clearInterval(gameState.gameLoop);
                draw();
                return;
            }

            gameState.snake.unshift([newX, newY]);

            if (newX === gameState.food[0] && newY === gameState.food[1]) {
                gameState.score++;
                document.getElementById('score').textContent = `Score: ${gameState.score}`;
                gameState.food = getNewFoodPosition();
            } else {
                gameState.snake.pop();
            }

            draw();
        }

        function startGame() {
            if (gameState.running) return;
            gameState.running = true;
            gameState.gameLoop = setInterval(() => {
                tick();
            }, 100);
        }

        function pauseGame() {
            if (gameState.gameLoop) {
                clearInterval(gameState.gameLoop);
                gameState.gameLoop = null;
                gameState.running = false;
            }
        }

        function resetGame() {
            pauseGame();
            gameState.snake = [[10, 10], [9, 10], [8, 10]];
            gameState.food = [15, 15];
            gameState.direction = 'right';
            gameState.nextDirection = 'right';
            gameState.score = 0;
            gameState.alive = true;
            document.getElementById('score').textContent = `Score: 0`;
            draw();
        }

        // Event listeners
        document.getElementById('start').addEventListener('click', startGame);
        document.getElementById('pause').addEventListener('click', pauseGame);
        document.getElementById('reset').addEventListener('click', resetGame);

        document.addEventListener('keydown', (e) => {
            const key = e.key.toLowerCase();
            if (key === 'arrowup' || key === 'w') {
                if (gameState.direction !== 'down') {
                    gameState.nextDirection = 'up';
                }
                e.preventDefault();
            } else if (key === 'arrowdown' || key === 's') {
                if (gameState.direction !== 'up') {
                    gameState.nextDirection = 'down';
                }
                e.preventDefault();
            } else if (key === 'arrowleft' || key === 'a') {
                if (gameState.direction !== 'right') {
                    gameState.nextDirection = 'left';
                }
                e.preventDefault();
            } else if (key === 'arrowright' || key === 'd') {
                if (gameState.direction !== 'left') {
                    gameState.nextDirection = 'right';
                }
                e.preventDefault();
            }
        });

        // Expose API to window
        window.game = {
            w: GRID_SIZE,
            h: GRID_SIZE,
            reset() {
                resetGame();
            },
            tick() {
                tick();
            },
            setDir(direction) {
                if (['up', 'down', 'left', 'right'].includes(direction)) {
                    // Prevent 180° reversal
                    if (gameState.direction === 'up' && direction === 'down') return;
                    if (gameState.direction === 'down' && direction === 'up') return;
                    if (gameState.direction === 'left' && direction === 'right') return;
                    if (gameState.direction === 'right' && direction === 'left') return;
                    gameState.nextDirection = direction;
                }
            },
            setFood(x, y) {
                gameState.food = [x, y];
                draw();
            },
            snake() {
                return gameState.snake.map(segment => [...segment]);
            },
            food() {
                return [...gameState.food];
            },
            alive() {
                return gameState.alive;
            },
            score() {
                return gameState.score;
            }
        };

        // Initial draw
        resetGame();
    </script>
</body>
</html>
